/**
 * Plugin discovery, activation and deactivation.
 *
 * Built-ins are served over HTTP from `public/plugins/<id>/` (the list of ids lives in
 * `public/builtin-plugins.json`, both generated by the plugin build). External plugins
 * are read from `<appData>/plugins/<id>/` through the Rust side. Both paths end in
 * {@link evaluatePlugin}: a CommonJS bundle evaluated with a `require` that resolves
 * only the modules in {@link HOST_MODULES}.
 */

import {
  disposeAll,
  type NaviShellPlugin,
  type PluginContext,
  type PluginManifest,
} from '@navishell/plugin-api';

import { call, errorMessage } from '../ipc/client';
import { removePluginResources, t } from '../i18n';
import { closePanel } from '../services/layout';
import { getAppInfo, getSettings, useSettingsStore } from '../stores/settings';
import { usePluginsStore, type PluginEntry } from '../stores/plugins';
import { compareVersions } from '../util/fn';
import { createPluginContext } from './context';
import { createPluginRequire } from './hostModules';
import { listPanelEntries, useRegistryStore } from './registry';

const BUILTIN_PREFIX = 'builtin://';

interface LoadedPlugin {
  plugin: NaviShellPlugin;
  ctx: PluginContext;
  styles: HTMLStyleElement[];
}

const loaded = new Map<string, LoadedPlugin>();

export function isPluginLoaded(id: string): boolean {
  return loaded.has(id);
}

// ---------------------------------------------------------------------------
// Discovery
// ---------------------------------------------------------------------------

function builtinDirId(entry: PluginEntry): string {
  return entry.dir.startsWith(BUILTIN_PREFIX) ? entry.dir.slice(BUILTIN_PREFIX.length) : entry.id;
}

function stubManifest(id: string): PluginManifest {
  return { id, name: id, version: '0.0.0' };
}

async function discoverBuiltins(): Promise<PluginEntry[]> {
  let ids: string[];
  try {
    const response = await fetch('/builtin-plugins.json');
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const parsed: unknown = await response.json();
    ids = Array.isArray(parsed) ? parsed.filter((id): id is string => typeof id === 'string') : [];
  } catch (error) {
    console.warn('[navishell] no built-in plugin index found', error);
    return [];
  }

  const entries: PluginEntry[] = [];
  for (const dirId of ids) {
    const dir = `${BUILTIN_PREFIX}${dirId}`;
    try {
      const response = await fetch(`/plugins/${dirId}/plugin.json`);
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const manifest = (await response.json()) as PluginManifest;
      entries.push({
        id: manifest.id || dirId,
        manifest,
        source: 'builtin',
        dir,
        status: 'disabled',
      });
    } catch (error) {
      entries.push({
        id: dirId,
        manifest: stubManifest(dirId),
        source: 'builtin',
        dir,
        status: 'error',
        error: t('plugins.errors.manifest', { message: errorMessage(error) }),
      });
    }
  }
  return entries;
}

async function discoverExternals(): Promise<PluginEntry[]> {
  try {
    const list = await call('plugins_list_external', {});
    return list.map((info) => ({
      id: info.manifest.id,
      manifest: info.manifest,
      source: 'external' as const,
      dir: info.dir,
      status: info.error ? ('error' as const) : ('disabled' as const),
      error: info.error,
    }));
  } catch (error) {
    console.warn('[navishell] plugins_list_external failed', error);
    return [];
  }
}

export async function discoverPlugins(): Promise<PluginEntry[]> {
  const [builtins, externals] = await Promise.all([discoverBuiltins(), discoverExternals()]);
  const byId = new Map<string, PluginEntry>();
  for (const entry of [...builtins, ...externals]) byId.set(entry.id, entry);
  return [...byId.values()];
}

// ---------------------------------------------------------------------------
// Reading plugin files
// ---------------------------------------------------------------------------

async function readPluginFile(entry: PluginEntry, relPath: string): Promise<string> {
  if (entry.source === 'builtin') {
    const response = await fetch(`/plugins/${builtinDirId(entry)}/${relPath}`);
    if (!response.ok) throw new Error(`HTTP ${response.status} for ${relPath}`);
    return response.text();
  }
  return call('plugins_read_file', { pluginId: entry.id, relPath });
}

// ---------------------------------------------------------------------------
// Evaluation
// ---------------------------------------------------------------------------

function evaluatePlugin(pluginId: string, code: string): NaviShellPlugin {
  const moduleShim = { exports: {} as Record<string, unknown> };
  const requireShim = createPluginRequire(pluginId);
  // Plugin bundles are CommonJS and are compiled at build time, not here; the host
  // controls both the code it fetches and the modules `require` can reach.
  const factory = new Function('module', 'exports', 'require', code) as (
    module: { exports: Record<string, unknown> },
    exports: Record<string, unknown>,
    require: (specifier: string) => unknown,
  ) => void;

  factory(moduleShim, moduleShim.exports, requireShim);

  const exported = moduleShim.exports;
  const candidate = (exported.default ?? exported) as NaviShellPlugin | undefined;
  if (!candidate || typeof candidate.activate !== 'function') {
    throw new Error(t('plugins.errors.noExport'));
  }
  return candidate;
}

// ---------------------------------------------------------------------------
// Activation
// ---------------------------------------------------------------------------

export async function activatePlugin(entry: PluginEntry): Promise<void> {
  const store = usePluginsStore.getState();
  if (loaded.has(entry.id)) return;

  if (getSettings().plugins.disabled.includes(entry.id)) {
    store.setStatus(entry.id, 'disabled', undefined);
    return;
  }

  // When `app_info` is unavailable (e.g. the app running outside Tauri) the version
  // check is skipped rather than failing every plugin.
  const appVersion = getAppInfo()?.version;
  const hostVersion = appVersion ?? '0.0.0';
  try {
    const minHostVersion = entry.manifest.minHostVersion;
    if (minHostVersion && appVersion && compareVersions(appVersion, minHostVersion) < 0) {
      throw new Error(
        t('plugins.errors.hostVersion', { required: minHostVersion, actual: hostVersion }),
      );
    }

    const code = await readPluginFile(entry, entry.manifest.main ?? 'main.js');

    const styles: HTMLStyleElement[] = [];
    for (const relPath of entry.manifest.styles ?? []) {
      try {
        const css = await readPluginFile(entry, relPath);
        const element = document.createElement('style');
        element.dataset.pluginId = entry.id;
        element.textContent = css;
        document.head.appendChild(element);
        styles.push(element);
      } catch (error) {
        console.warn(`[navishell] could not load style ${relPath} of ${entry.id}`, error);
      }
    }

    const plugin = evaluatePlugin(entry.id, code);
    const ctx = createPluginContext({
      manifest: entry.manifest,
      hostVersion,
      pluginDir: entry.dir,
    });
    loaded.set(entry.id, { plugin, ctx, styles });

    await plugin.activate(ctx);
    usePluginsStore.getState().setStatus(entry.id, 'active', undefined);
  } catch (error) {
    const message = errorMessage(error);
    console.error(`[navishell] plugin ${entry.id} failed to activate`, error);
    await teardown(entry.id);
    usePluginsStore.getState().setStatus(entry.id, 'error', message);
  }
}

async function teardown(id: string): Promise<void> {
  const record = loaded.get(id);
  loaded.delete(id);

  if (record) {
    try {
      await record.plugin.deactivate?.();
    } catch (error) {
      console.error(`[navishell] plugin ${id} failed to deactivate`, error);
    }
    disposeAll(record.ctx.subscriptions);
    for (const element of record.styles) element.remove();
  }

  for (const entry of listPanelEntries()) {
    if (entry.kind === 'plugin' && entry.pluginId === id) closePanel(entry.fullId);
  }
  useRegistryStore.getState().unregisterPlugin(id);
  removePluginResources(id);
}

export async function deactivatePlugin(id: string): Promise<void> {
  await teardown(id);
  usePluginsStore.getState().setStatus(id, 'disabled', undefined);
}

// ---------------------------------------------------------------------------
// Orchestration
// ---------------------------------------------------------------------------

/** Discover and activate every enabled plugin. Never throws. */
export async function loadPlugins(): Promise<void> {
  const store = usePluginsStore.getState();
  store.setLoading(true);
  try {
    const entries = await discoverPlugins();
    store.setEntries(entries);
    for (const entry of entries) {
      if (entry.status === 'error') continue;
      await activatePlugin(entry);
    }
  } catch (error) {
    console.error('[navishell] plugin loading failed', error);
  } finally {
    usePluginsStore.getState().setLoading(false);
  }
}

export async function setPluginEnabled(id: string, enabled: boolean): Promise<void> {
  useSettingsStore.getState().update((prev) => {
    const disabled = new Set(prev.plugins.disabled);
    if (enabled) disabled.delete(id);
    else disabled.add(id);
    return { ...prev, plugins: { ...prev.plugins, disabled: [...disabled] } };
  });

  const entry = usePluginsStore.getState().entries.find((e) => e.id === id);
  if (!entry) return;
  if (enabled) {
    await activatePlugin(entry);
  } else {
    await deactivatePlugin(id);
  }
}

/** Deactivate everything, rediscover and activate again. */
export async function reloadPlugins(): Promise<void> {
  for (const id of [...loaded.keys()]) await teardown(id);
  await loadPlugins();
}
